// Paisaje propio construido a partir de píxeles (sin utilizar recursos de videojuegos existentes).
function drawTitleLandscape(){
 const cv=$('titleCanvas'),g=cv.getContext('2d');g.imageSmoothingEnabled=false;
 const W=640,H=270;const seed=(x,y)=>{let v=Math.sin(x*73.8+y*43.2)*40329.2;return v-Math.floor(v)};
 const px=(x,y,w,h,c)=>{g.fillStyle=c;g.fillRect(x,y,w,h)};
 px(0,0,W,H,'#75b2d1');for(let y=0;y<162;y+=8)px(0,y,W,8,y<66?'#5e95ba':y<115?'#85b9d0':'#b0d4c9');
 px(480,20,56,56,'#f8dca0');px(489,13,40,70,'#fae3ad');px(472,29,72,37,'#fae3ad');
 for(let n=0;n<9;n++){let x=n*88-55,peak=65+(n%3)*16;g.fillStyle=n%2?'#628e9b':'#5c8298';g.beginPath();g.moveTo(x-100,169);g.lineTo(x+70,peak);g.lineTo(x+235,169);g.fill();px(x+58,peak+8,27,9,'#c0d5cf')}
 for(let y=160;y<H;y+=10)px(0,y,W,10,y%20===0?'#80af80':'#6da076');
 for(let i=0;i<95;i++){let x=Math.floor(seed(i,2)*W/4)*4,y=172+Math.floor(seed(i,6)*80/4)*4;px(x,y,4,4,seed(i,4)>.7?'#f3dc93':'#a6d89a')}
 for(let i=0;i<14;i++){let x=9+i*47+Math.floor(seed(i,7)*17),y=151+Math.floor(seed(i,8)*22);px(x+13,y+29,10,26,'#5c7054');px(x+1,y+15,34,28,'#2f765f');px(x+7,y+2,22,28,'#44896c');px(x+14,y-5,10,22,'#64a274');px(x+2,y+18,7,6,'#72af84')}
 // Senda en píxeles: forma parte del paisaje y del viaje que empieza en Pueblo Paleta.
 g.fillStyle='#bfaa7c';g.beginPath();g.moveTo(252,270);g.lineTo(293,165);g.lineTo(338,165);g.lineTo(408,270);g.fill();
 g.fillStyle='#e2c798';g.beginPath();g.moveTo(270,270);g.lineTo(300,167);g.lineTo(323,167);g.lineTo(378,270);g.fill();
 for(let i=0;i<20;i++){let x=Math.floor(seed(i,9)*W/4)*4,y=222+Math.floor(seed(i,10)*10)*4;px(x,y,4,4,'#d9c38b')}
 // Casita lejana y Poké Ball abstracta, en puro pixel art.
 px(302,151,40,24,'#f1e0b7');px(294,140,56,12,'#c36a65');px(300,132,44,10,'#e58e74');px(319,158,9,17,'#6b594e');px(308,157,7,8,'#91bbbd');
}
try{drawTitleLandscape()}catch(e){console.warn('Paisaje',e)}
for(const sid of [1,4,7])fetchSprite(sid);
